def min_window(s: str, t: str) -> str:
    if not s or not t:
        return ''

    start = 0
    end = 0
    window_count = 0
    min_length = float('inf')

    for i in range(len(s)):
        if i > start and i <= end:
            window_count += 1
            if window_count == 1:
                min_length = min(min_length, s[start:i+1])
            else:
                min_length = min(min_length, s[start:i+1])
            start += 1
        elif i > start and i <= end:
            window_count -= 1
            if window_count == 0:
                min_length = min(min_length, s[start:i+1])
            else:
                min_length = min(min_length, s[start:i+1])
            start += 1
        else:
            end = i

    if min_length == float('inf'):
        return ''
    else:
        return s[start:end+1]
```
