def lis_length(nums: list[int]) -> int:
    """
    Given a list of integers, return the length of the longest strictly increasing subsequence.
    The solution must handle 10^5 elements in well under one second, so it needs O(n log n) time.
    """
    tails = []
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            l, r = 0, len(tails) - 1
            while l <= r:
                if tails[l] < num:
                    l += 1
                else:
                    r -= 1
            tails[l] = num
    return len(tails)
```
