def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    nodes = list(range(n))
    distances = [float('inf')] * n
    for u, v, w in edges:
        if u == src:
            distances[u] = 0
        elif v == src:
            distances[v] = 0
        else:
            distances[v] = distances[u] + w
    result = []
    for i in range(n):
        if distances[i] == float('inf'):
            result.append(i)
        else:
            result.append(i)
    return result
```

